import{_ as r,o as t,c as l,a3 as a}from"./chunks/framework.BrO6lPIi.js";const b=JSON.parse('{"title":"故障排除与常见问题","description":"两端通过本地 HTTP/WebSocket 通信；Agent 源码修改后必须重启进程，新接口才生效。","frontmatter":{"title":"故障排除与常见问题","description":"两端通过本地 HTTP/WebSocket 通信；Agent 源码修改后必须重启进程，新接口才生效。"},"headers":[],"relativePath":"故障排除与常见问题/index.md","filePath":"故障排除与常见问题/index.md","lastUpdated":null}'),i={name:"故障排除与常见问题/index.md"};function n(o,e,s,g,c,h){return t(),l("div",null,[...e[0]||(e[0]=[a(`<h1 id="故障排除与常见问题" tabindex="-1">故障排除与常见问题 <a class="header-anchor" href="#故障排除与常见问题" aria-label="Permalink to &quot;故障排除与常见问题&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.md" target="_blank" rel="noreferrer">README.md</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json" target="_blank" rel="noreferrer">manifest.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json" target="_blank" rel="noreferrer">package.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json" target="_blank" rel="noreferrer">agent/package.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.md" target="_blank" rel="noreferrer">agent/README.md</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js" target="_blank" rel="noreferrer">src/background/index.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js" target="_blank" rel="noreferrer">src/background/react-loop.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/auto-resume.js" target="_blank" rel="noreferrer">src/background/auto-resume.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js" target="_blank" rel="noreferrer">src/background/tool-executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js" target="_blank" rel="noreferrer">src/background/local-agent-client.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/install-guide.js" target="_blank" rel="noreferrer">src/options/install-guide.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/logger.js" target="_blank" rel="noreferrer">src/shared/logger.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js" target="_blank" rel="noreferrer">src/storage/db.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#简介">简介</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能注意事项">性能注意事项</a></li><li><a href="#故障排除指南">故障排除指南</a></li><li><a href="#结论">结论</a></li><li><a href="#附录">附录</a></li></ol><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>本文件面向 AI Helper（扩展端）与本地 Agent 服务（代理端）的故障排除与常见问题。文档覆盖安装问题、运行问题、扩展相关问题、Agent 服务问题、调试工具与技巧，以及常见错误信息的含义和解决方案，并给出社区支持与反馈渠道。</p><p>本项目采用双进程架构：</p><ul><li>Chrome 扩展端：Manifest V3，Service Worker 作为 background，侧边栏为 side panel，版本 2.3.1。</li><li>独立本地 Agent 服务：Node.js 进程，npm 包名 ai-helper-agent，版本 2.3.1。</li></ul><p>两端通过本地 HTTP/WebSocket 通信；Agent 源码修改后必须重启进程，新接口才生效。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.md#L87-L94" target="_blank" rel="noreferrer">README.md#L87-L94</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L76" target="_blank" rel="noreferrer">manifest.json#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L1-L47" target="_blank" rel="noreferrer">package.json#L1-L47</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L1-L67" target="_blank" rel="noreferrer">agent/package.json#L1-L67</a></li></ul><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><ul><li>扩展端入口：<code>src/background/index.js</code>（Service Worker）。</li><li>侧边栏界面：<code>side_panel.html</code>，由 <code>manifest.json</code> 的 <code>side_panel.default_path</code> 指向。</li><li>选项页：<code>options.html</code>，用于配置 API Key、Agent 配对、知识库等。</li><li>Agent 服务端：<code>agent/src/server.js</code>，提供文件读写、命令执行、记忆、RAG、MCP、Skill 等能力。</li><li>安装引导：<code>src/options/install-guide.js</code> 生成与当前扩展版本一致的 Agent 安装命令。</li><li>日志系统：扩展端使用 <code>src/shared/logger.js</code>；Agent 端将审计日志写入 <code>~/.ai-helper-agent/logs/</code>。</li></ul><pre class="mermaid">graph TB
A[&quot;浏览器&quot;] --&gt; B[&quot;Chrome 扩展&lt;br/&gt;Service Worker&quot;]
B --&gt; C[&quot;侧边栏面板&quot;]
B --&gt; D[&quot;工具执行器&quot;]
D --&gt; E[&quot;本地 Agent 客户端&quot;]
E --&gt; F[&quot;Agent 服务&lt;br/&gt;HTTP + WebSocket&quot;]
F --&gt; G[&quot;文件系统 / 命令执行 / 记忆 / RAG / MCP / Skill&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L47-L53" target="_blank" rel="noreferrer">manifest.json#L47-L53</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1-L120" target="_blank" rel="noreferrer">src/background/index.js#L1-L120</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L76" target="_blank" rel="noreferrer">manifest.json#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/install-guide.js#L1-L77" target="_blank" rel="noreferrer">src/options/install-guide.js#L1-L77</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.md#L186-L235" target="_blank" rel="noreferrer">agent/README.md#L186-L235</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li>Service Worker 生命周期管理：keepalive 端口、自动续跑闹钟、SW 重启检测、侧边栏可见性。</li><li>ReAct 推理循环：任务拆解、工具调用、超时、循环检测、完成度校验。</li><li>Agent 客户端：配对、认证、HTTP/WebSocket 封装、可达性缓存、多代理支持。</li><li>Agent 服务器：请求路由、CORS、认证、文件沙箱、命令分级安全、日志、更新与重启。</li><li>存储层：IndexedDB 会话、checkpoint、定时任务、书签、Token 统计。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L120-L218" target="_blank" rel="noreferrer">src/background/index.js#L120-L218</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1-L120" target="_blank" rel="noreferrer">src/background/react-loop.js#L1-L120</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L98" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L98</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L548" target="_blank" rel="noreferrer">agent/src/server.js#L388-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L21-L122" target="_blank" rel="noreferrer">src/storage/db.js#L21-L122</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>扩展端通过 <code>local-agent-client.js</code> 向 Agent 发起认证后的 HTTP 请求；命令执行还建立 WebSocket 流式输出。Agent 端对每个请求进行语言设置、CORS、URL 解析、认证、业务处理，并把异常统一捕获返回 500，避免单点错误拖垮整个服务。</p><pre class="mermaid">sequenceDiagram
participant UI as &quot;侧边栏&quot;
participant BG as &quot;Service Worker&quot;
participant TE as &quot;工具执行器&quot;
participant AC as &quot;Agent 客户端&quot;
participant AG as &quot;Agent 服务&quot;
UI-&gt;&gt;BG : 发送用户指令
BG-&gt;&gt;TE : 选择工具并准备参数
TE-&gt;&gt;AC : 调用 Agent API
AC-&gt;&gt;AG : POST /api/* (Bearer Token)
AG--&gt;&gt;AC : JSON 响应
AC--&gt;&gt;TE : 结果或错误
TE--&gt;&gt;BG : 工具执行结果
BG--&gt;&gt;UI : 渲染消息/状态
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1-L23" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L392-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L392-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L464" target="_blank" rel="noreferrer">agent/src/server.js#L417-L464</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L392-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L392-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L548" target="_blank" rel="noreferrer">agent/src/server.js#L417-L548</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="service-worker-生命周期与保活" tabindex="-1">Service Worker 生命周期与保活 <a class="header-anchor" href="#service-worker-生命周期与保活" aria-label="Permalink to &quot;Service Worker 生命周期与保活&quot;">​</a></h3><ul><li>keepalive 端口：侧边栏通过 <code>chrome.runtime.connect</code> 建立长连接，防止 SW 空闲被杀。</li><li>SW 重启检测：重连时若 sessionId 不在活跃集合中，说明 SW 已重启，会下发 <code>SW_RESTARTED</code> 并携带可恢复 checkpoint。</li><li>自动续跑：主任务期间注册 30 秒周期闹钟；SW 被回收后由闹钟唤醒，扫描残留 checkpoint 自动续跑，最多尝试固定次数，耗尽后提示人工介入。</li><li>侧边栏开关与分组：全局模式与标签页绑定模式分别处理，避免“能开不能关”“面板泄露到新 tab”等问题。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;SW 启动&quot;]) --&gt; Keepalive[&quot;注册 keepalive 端口&quot;]
Keepalive --&gt; DetectRestart{&quot;是否重连且会话不在活跃集合？&quot;}
DetectRestart --&gt; |是| SendRestart[&quot;发送 SW_RESTARTED 并附带 checkpoint&quot;]
DetectRestart --&gt; |否| Normal[&quot;正常处理消息&quot;]
Normal --&gt; WatchAlarm[&quot;注册自动续跑闹钟&quot;]
SendRestart --&gt; WatchAlarm
WatchAlarm --&gt; AlarmTick{&quot;闹钟触发&quot;}
AlarmTick --&gt; Decide[&quot;决策：是否应续跑&quot;]
Decide --&gt; |是| Resume[&quot;从 checkpoint 恢复执行&quot;]
Decide --&gt; |否| Idle[&quot;等待下一次闹钟&quot;]
Resume --&gt; CheckAttempts{&quot;是否已达最大尝试次数？&quot;}
CheckAttempts --&gt; |是| NotifyExhausted[&quot;通知人工介入&quot;]
CheckAttempts --&gt; |否| Continue[&quot;继续执行&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L140-L218" target="_blank" rel="noreferrer">src/background/index.js#L140-L218</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/auto-resume.js#L39-L112" target="_blank" rel="noreferrer">src/background/auto-resume.js#L39-L112</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L120-L218" target="_blank" rel="noreferrer">src/background/index.js#L120-L218</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/auto-resume.js#L1-L119" target="_blank" rel="noreferrer">src/background/auto-resume.js#L1-L119</a></li></ul><h3 id="react-推理循环与完成度校验" tabindex="-1">ReAct 推理循环与完成度校验 <a class="header-anchor" href="#react-推理循环与完成度校验" aria-label="Permalink to &quot;ReAct 推理循环与完成度校验&quot;">​</a></h3><ul><li>工具预筛选减少 token 消耗。</li><li>子任务计划与完成度校验：基于 DOM/命令证据验证子任务目标，未满足时可自动重试或跳过。</li><li>循环检测：重复无效操作、页面元素枚举循环、操作振荡、连续失败、无进展滚动、预算耗尽等场景会暂停任务并提示补充指导。</li><li>流式响应空闲超时：长时间无数据则中断，提示网络或服务提供商不稳定。</li></ul><pre class="mermaid">flowchart TD
Enter([&quot;进入 ReAct 循环&quot;]) --&gt; Preselect[&quot;工具预筛选&quot;]
Preselect --&gt; Plan[&quot;规划子任务&quot;]
Plan --&gt; Execute[&quot;执行工具&quot;]
Execute --&gt; Verify{&quot;完成度校验通过？&quot;}
Verify --&gt; |是| NextRound[&quot;下一轮&quot;]
Verify --&gt; |否| RetryOrSkip[&quot;重试或跳过&quot;]
NextRound --&gt; LoopCheck{&quot;是否检测到循环？&quot;}
LoopCheck --&gt; |是| Pause[&quot;暂停并提示补充指导&quot;]
LoopCheck --&gt; |否| Execute
RetryOrSkip --&gt; LoopCheck
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L22-L100" target="_blank" rel="noreferrer">src/background/react-loop.js#L22-L100</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1-L23" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1-L23</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1-L200" target="_blank" rel="noreferrer">src/background/react-loop.js#L1-L200</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1-L250" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1-L250</a></li></ul><h3 id="agent-客户端与服务端通信" tabindex="-1">Agent 客户端与服务端通信 <a class="header-anchor" href="#agent-客户端与服务端通信" aria-label="Permalink to &quot;Agent 客户端与服务端通信&quot;">​</a></h3><ul><li>配对流程：扩展端 POST <code>/api/pair</code>，成功后保存 token 并设为活跃代理。</li><li>认证请求：所有需认证的请求带 Bearer Token，GET/POST 均封装在 <code>agentGet</code>/<code>agentRequest</code>。</li><li>可达性缓存：已知不可达时直接返回错误，避免阻塞等待超时。</li><li>WebSocket：命令执行实时输出，token 通过查询参数附加。</li></ul><pre class="mermaid">sequenceDiagram
participant Ext as &quot;扩展端&quot;
participant AC as &quot;Agent 客户端&quot;
participant AG as &quot;Agent 服务&quot;
Ext-&gt;&gt;AC : pairWithAgent(url, code)
AC-&gt;&gt;AG : POST /api/pair
AG--&gt;&gt;AC : {success, token}
AC-&gt;&gt;Ext : 保存 token 并标记活跃
Ext-&gt;&gt;AC : agentRequest(path, body)
AC-&gt;&gt;AG : POST /api/* (Authorization : Bearer token)
AG--&gt;&gt;AC : JSON 响应
AC--&gt;&gt;Ext : 结果或错误
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L275-L330" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L275-L330</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L392-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L392-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L474-L548" target="_blank" rel="noreferrer">agent/src/server.js#L474-L548</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L275-L330" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L275-L330</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L392-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L392-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L474-L548" target="_blank" rel="noreferrer">agent/src/server.js#L474-L548</a></li></ul><h3 id="agent-服务启动、认证与安全" tabindex="-1">Agent 服务启动、认证与安全 <a class="header-anchor" href="#agent-服务启动、认证与安全" aria-label="Permalink to &quot;Agent 服务启动、认证与安全&quot;">​</a></h3><ul><li>启动：加载配置、初始化搜索工具、检测 RAG 能力、启动 HTTP 与 WebSocket。</li><li>CORS：仅放行 <code>chrome-extension://</code> 来源，保护无认证端点。</li><li>认证：Bearer Token 校验，缺失或无效返回 401/403。</li><li>安全：文件路径白名单、命令黑名单/灰名单、进程树终止、审计日志。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;startServer&quot;]) --&gt; LoadConfig[&quot;加载配置&quot;]
LoadConfig --&gt; InitSearch[&quot;初始化搜索工具&quot;]
InitSearch --&gt; DetectRAG[&quot;检测 RAG 可用性&quot;]
DetectRAG --&gt; Listen[&quot;监听 HTTP/WebSocket&quot;]
Listen --&gt; HandleReq[&quot;处理请求&quot;]
HandleReq --&gt; ParseURL[&quot;解析 URL&quot;]
ParseURL --&gt; Auth{&quot;是否需要认证？&quot;}
Auth --&gt; |否| Public[&quot;公开接口：/api/pair, /api/status&quot;]
Auth --&gt; |是| Verify[&quot;验证 Bearer Token&quot;]
Verify --&gt; Route[&quot;路由到具体功能&quot;]
Public --&gt; Route
Route --&gt; Log[&quot;记录审计日志&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L444-L548" target="_blank" rel="noreferrer">agent/src/server.js#L444-L548</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L548" target="_blank" rel="noreferrer">agent/src/server.js#L388-L548</a></li></ul><h3 id="数据存储与恢复" tabindex="-1">数据存储与恢复 <a class="header-anchor" href="#数据存储与恢复" aria-label="Permalink to &quot;数据存储与恢复&quot;">​</a></h3><ul><li>IndexedDB：会话、归档、原型、Token 统计、ReAct checkpoint、书签、定时任务。</li><li>checkpoint TTL：7 天，过期清理。</li><li>连接恢复：store 不存在时关闭旧连接并重试，避免升级阻塞导致 checkpoint 静默失败。</li></ul><pre class="mermaid">flowchart TD
OpenDB[&quot;打开数据库&quot;] --&gt; Upgrade{&quot;版本变更？&quot;}
Upgrade --&gt; |是| CloseOld[&quot;关闭旧连接&quot;]
CloseOld --&gt; ResetCache[&quot;重置连接缓存&quot;]
ResetCache --&gt; Reopen[&quot;重新打开数据库&quot;]
Upgrade --&gt; |否| UseDB[&quot;使用现有连接&quot;]
UseDB --&gt; WithStore[&quot;withStore 事务包装&quot;]
WithStore --&gt; StoreExists{&quot;store 是否存在？&quot;}
StoreExists --&gt; |否| CloseAndRetry[&quot;关闭并延迟重试&quot;]
StoreExists --&gt; |是| ExecTx[&quot;执行事务&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L35-L122" target="_blank" rel="noreferrer">src/storage/db.js#L35-L122</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L154-L200" target="_blank" rel="noreferrer">src/storage/db.js#L154-L200</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L21-L122" target="_blank" rel="noreferrer">src/storage/db.js#L21-L122</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L154-L200" target="_blank" rel="noreferrer">src/storage/db.js#L154-L200</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li>扩展端依赖 Manifest V3 能力：sidePanel、scripting、storage、alarms、debugger 等。</li><li>Agent 端依赖 Node.js &gt;= 18，可选 fd/rg 加速搜索，RAG 可选依赖 vectra、transformers、pdf-parse 等。</li><li>构建脚本：扩展端使用 vite，Agent 端发布脚本复制 dist。</li></ul><pre class="mermaid">graph LR
MV3[&quot;Manifest V3 权限&quot;] --&gt; BG[&quot;Service Worker&quot;]
BG --&gt; Tools[&quot;工具执行器&quot;]
Tools --&gt; AgentClient[&quot;Agent 客户端&quot;]
AgentClient --&gt; AgentServer[&quot;Agent 服务&quot;]
AgentServer --&gt; FS[&quot;文件系统&quot;]
AgentServer --&gt; Exec[&quot;命令执行&quot;]
AgentServer --&gt; Memory[&quot;长期记忆&quot;]
AgentServer --&gt; RAG[&quot;知识库&quot;]
AgentServer --&gt; MCP[&quot;MCP 协议&quot;]
AgentServer --&gt; Skill[&quot;技能系统&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L7-L27" target="_blank" rel="noreferrer">manifest.json#L7-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L26-L40" target="_blank" rel="noreferrer">agent/package.json#L26-L40</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L7-L27" target="_blank" rel="noreferrer">manifest.json#L7-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L26-L40" target="_blank" rel="noreferrer">agent/package.json#L26-L40</a></li></ul><h2 id="性能注意事项" tabindex="-1">性能注意事项 <a class="header-anchor" href="#性能注意事项" aria-label="Permalink to &quot;性能注意事项&quot;">​</a></h2><ul><li>ReAct 循环 token 预算按 token 计数而非消息数，避免 tool_calls/tool 消息对被截断。</li><li>大页面选择内容会被摘要压缩，减少上下文占用。</li><li>Agent 端命令执行支持进程树终止，避免孤儿进程持续写盘。</li><li>向量索引重建与模型指纹变化会触发缓存失效，避免维度不匹配比较。</li></ul><p>[本节为通用性能建议，不直接分析具体文件]</p><h2 id="故障排除指南" tabindex="-1">故障排除指南 <a class="header-anchor" href="#故障排除指南" aria-label="Permalink to &quot;故障排除指南&quot;">​</a></h2><h3 id="安装问题" tabindex="-1">安装问题 <a class="header-anchor" href="#安装问题" aria-label="Permalink to &quot;安装问题&quot;">​</a></h3><ul><li>权限配置 <ul><li>确保以官方渠道安装扩展：Chrome Web Store 或 Edge Add-ons，或从 GitHub Releases 下载 zip 并在开发者模式下加载。</li><li>Agent 一键安装脚本会自动检测网络环境并安装 Node.js 运行时；Windows 使用 PowerShell 管道执行。</li><li>若手动 npm 安装，需 Node.js &gt;= 18；RAG 功能推荐 Node.js &gt;= 22.13.0。</li></ul></li><li>依赖冲突 <ul><li>RAG 依赖缺失时，Agent 启动时会检测并提供自动恢复；npm -g 升级可能清空包目录内依赖，Agent 会重新安装。</li><li>更新 Agent 与 RAG 依赖安装互斥，避免并发写 node_modules 破坏依赖。</li></ul></li><li>浏览器兼容性 <ul><li>需要 Chrome / Edge / Chromium 114+，因为使用 Side Panel API。</li><li>Manifest V3 要求 Service Worker 作为 background，注意 SW 生命周期硬约束。</li></ul></li><li>网络问题 <ul><li>扩展端与 Agent 通信使用本地 HTTP/WebSocket；若代理地址为 0.0.0.0，客户端会替换为 127.0.0.1 或配置的 hostname。</li><li>内网访问受网络范围控制，需在扩展设置中开启“内网地址访问”并将主机加入允许列表。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.md#L87-L94" target="_blank" rel="noreferrer">README.md#L87-L94</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.md#L7-L30" target="_blank" rel="noreferrer">agent/README.md#L7-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.md#L487-L489" target="_blank" rel="noreferrer">agent/README.md#L487-L489</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L674-L690" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L674-L690</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L44-L47" target="_blank" rel="noreferrer">src/background/tool-executor.js#L44-L47</a></li></ul><h3 id="运行问题" tabindex="-1">运行问题 <a class="header-anchor" href="#运行问题" aria-label="Permalink to &quot;运行问题&quot;">​</a></h3><ul><li>Service Worker 生命周期 <ul><li>现象：任务中途消失、侧边栏断开、API 调用中断。</li><li>排查：检查 keepalive 端口是否建立，SW 是否重启；查看后台日志中的 <code>SW_RESTARTED</code> 与 checkpoint 相关条目。</li><li>解决：确认侧边栏保持打开；必要时点击“继续执行”恢复；检查自动续跑是否达到最大尝试次数。</li></ul></li><li>内存泄漏排查 <ul><li>现象：Agent 内存持续增长、命令执行后进程残留。</li><li>排查：查看 Agent <code>/api/status/detail</code> 的 <code>resourceUsage</code>；检查命令执行是否被正确终止；查看审计日志中的 exec 类别。</li><li>解决：停止命令执行；重启 Agent；确认进程树终止逻辑生效。</li></ul></li><li>性能瓶颈分析 <ul><li>现象：工具调用慢、流式响应卡顿。</li><li>排查：检查工具预筛选是否生效；查看 ReAct 循环迭代次数；检查网络范围限制是否频繁拒绝。</li><li>解决：缩小任务范围；调整 timeout；确认服务提供商可用。</li></ul></li><li>日志分析方法 <ul><li>扩展端：使用 <code>src/shared/logger.js</code>，控制台输出 <code>[AIH]</code> 前缀。</li><li>Agent 端：终端前台模式实时输出；文件日志位于 <code>~/.ai-helper-agent/logs/</code>，JSON Lines 格式，支持按日期/类别查询。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L140-L218" target="_blank" rel="noreferrer">src/background/index.js#L140-L218</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/auto-resume.js#L39-L112" target="_blank" rel="noreferrer">src/background/auto-resume.js#L39-L112</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L725-L748" target="_blank" rel="noreferrer">agent/src/server.js#L725-L748</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.md#L186-L235" target="_blank" rel="noreferrer">agent/README.md#L186-L235</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/logger.js#L1-L51" target="_blank" rel="noreferrer">src/shared/logger.js#L1-L51</a></li></ul><h3 id="扩展相关问题" tabindex="-1">扩展相关问题 <a class="header-anchor" href="#扩展相关问题" aria-label="Permalink to &quot;扩展相关问题&quot;">​</a></h3><ul><li>更新失败处理 <ul><li>现象：Agent 更新失败，前端提示更新失败。</li><li>原因：npm 安装超时或退出码非 0；与 RAG 依赖安装并发被拒绝。</li><li>解决：稍后重试；检查网络代理配置；手动执行 <code>npm install -g ai-helper-agent@latest</code>。</li></ul></li><li>配置重置方法 <ul><li>现象：Agent 配置异常、工作目录错误。</li><li>解决：编辑 <code>~/.ai-helper-agent/config.json</code>；或通过扩展设置页重置 Agent 配置。</li></ul></li><li>数据恢复步骤 <ul><li>现象：任务中断后无法恢复。</li><li>原因：checkpoint 过期或被清理；IndexedDB store 缺失。</li><li>解决：检查 <code>reactCheckpoints</code> store 是否存在；必要时清理过期 checkpoint 后重试；确认自动续跑未耗尽。</li></ul></li><li>卸载清理 <ul><li>现象：卸载后仍有残留进程或文件。</li><li>解决：使用 Agent CLI <code>uninstall</code>；手动删除 <code>~/.ai-helper-agent/</code> 下数据；确认 PID 文件已清理。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L605-L719" target="_blank" rel="noreferrer">agent/src/server.js#L605-L719</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.md#L144-L169" target="_blank" rel="noreferrer">agent/README.md#L144-L169</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L24-L29" target="_blank" rel="noreferrer">src/storage/db.js#L24-L29</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.md#L90-L99" target="_blank" rel="noreferrer">agent/README.md#L90-L99</a></li></ul><h3 id="agent-服务问题" tabindex="-1">Agent 服务问题 <a class="header-anchor" href="#agent-服务问题" aria-label="Permalink to &quot;Agent 服务问题&quot;">​</a></h3><ul><li>启动失败 <ul><li>现象：Agent 无法启动，端口冲突。</li><li>排查：检查端口配置；查看启动日志；确认 Node.js 版本。</li><li>解决：更换端口；重启服务；检查防火墙或代理设置。</li></ul></li><li>连接异常 <ul><li>现象：扩展端提示“无法连接到 Agent”。</li><li>排查：检查配对是否成功；Token 是否有效；代理地址是否正确。</li><li>解决：重新配对；确认代理在线；检查可达性缓存。</li></ul></li><li>权限拒绝 <ul><li>现象：命令执行被拒绝，文件操作受限。</li><li>排查：查看安全日志；确认命令是否在黑名单；检查文件路径是否在白名单。</li><li>解决：调整 allowedPaths；确认命令无需高危操作；必要时用户确认。</li></ul></li><li>资源占用过高 <ul><li>现象：CPU/内存飙升。</li><li>排查：查看 <code>/api/status/detail</code> 的资源使用；检查是否有长时间运行的命令。</li><li>解决：停止命令；重启 Agent；优化 RAG 索引重建频率。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L725-L748" target="_blank" rel="noreferrer">agent/src/server.js#L725-L748</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.md#L100-L143" target="_blank" rel="noreferrer">agent/README.md#L100-L143</a></li></ul><h3 id="调试工具与技巧" tabindex="-1">调试工具与技巧 <a class="header-anchor" href="#调试工具与技巧" aria-label="Permalink to &quot;调试工具与技巧&quot;">​</a></h3><ul><li>日志查看 <ul><li>扩展端：控制台过滤 <code>[AIH]</code>；后台日志关注 checkpoint、SW 重启、自动续跑。</li><li>Agent 端：前台模式实时输出；文件日志按日期分类；支持 <code>/api/logs</code> 查询。</li></ul></li><li>性能监控 <ul><li>扩展端：观察 ReAct 循环迭代次数、工具调用耗时。</li><li>Agent 端：查看 <code>/api/status/detail</code> 的 memoryUsedMB、uptimeSeconds、cpuUser/System。</li></ul></li><li>网络抓包 <ul><li>使用浏览器开发者工具的 Network 面板查看扩展端与 Agent 的 HTTP 请求。</li><li>使用 WebSocket 面板查看命令执行实时输出。</li></ul></li><li>内存分析 <ul><li>使用 Chrome DevTools 的 Memory 面板分析 Service Worker 内存。</li><li>使用 Node.js 的 <code>process.memoryUsage()</code> 或 Agent 提供的资源信息分析 Agent 内存。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/logger.js#L1-L51" target="_blank" rel="noreferrer">src/shared/logger.js#L1-L51</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.md#L186-L235" target="_blank" rel="noreferrer">agent/README.md#L186-L235</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L725-L748" target="_blank" rel="noreferrer">agent/src/server.js#L725-L748</a></li></ul><h3 id="常见错误信息与解决方案" tabindex="-1">常见错误信息与解决方案 <a class="header-anchor" href="#常见错误信息与解决方案" aria-label="Permalink to &quot;常见错误信息与解决方案&quot;">​</a></h3><ul><li>“无法连接到 Agent” <ul><li>含义：扩展端无法与 Agent 建立连接。</li><li>解决：确认 Agent 已启动；检查配对状态；验证代理地址。</li></ul></li><li>“代理服务未连接” <ul><li>含义：Agent 客户端已知代理不可达。</li><li>解决：重启 Agent；检查网络；清除可达性缓存。</li></ul></li><li>“请求超时” <ul><li>含义：HTTP 请求超过设定时间。</li><li>解决：增大 timeout；检查网络稳定性；确认服务提供商可用。</li></ul></li><li>“命令执行被拒绝” <ul><li>含义：命令命中黑名单或灰名单未确认。</li><li>解决：调整命令策略；用户确认；避免高危操作。</li></ul></li><li>“更新失败” <ul><li>含义：Agent 更新过程中 npm 安装失败。</li><li>解决：检查网络代理；手动执行更新命令；稍后重试。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L11-L38" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L11-L38</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L117-L184" target="_blank" rel="noreferrer">src/background/tool-executor.js#L117-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L605-L719" target="_blank" rel="noreferrer">agent/src/server.js#L605-L719</a></li></ul><h3 id="社区支持与问题反馈" tabindex="-1">社区支持与问题反馈 <a class="header-anchor" href="#社区支持与问题反馈" aria-label="Permalink to &quot;社区支持与问题反馈&quot;">​</a></h3><ul><li>GitHub Discussions：提问与讨论。</li><li>Issues：提交 bug 或功能请求。</li><li>承诺：每个 issue 会在 24 小时内回复。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.md#L106-L111" target="_blank" rel="noreferrer">README.md#L106-L111</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>AI Helper 的双进程架构提供了强大的网页自动化与本地能力，但也引入了 Service Worker 生命周期、Agent 通信、权限安全等复杂问题。通过本文的故障排除指南，用户可以快速定位安装、运行、扩展、Agent 相关的问题，并使用日志、性能监控、网络抓包等工具进行诊断。遇到问题时，优先检查配置、日志、权限和网络，再考虑社区支持。</p><p>[本节为总结性内容，不直接分析具体文件]</p><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><ul><li>快速参考： <ul><li>扩展版本：2.3.1</li><li>Agent 版本：2.3.1</li><li>最低浏览器版本：Chrome / Edge / Chromium 114+</li><li>最低 Node.js 版本：18（RAG 推荐 22.13.0+）</li></ul></li></ul><p>[本节为补充信息，不直接分析具体文件]</p>`,110)])])}const p=r(i,[["render",n]]);export{b as __pageData,p as default};
